function resolveAccess(rules, request) {
  if (!Array.isArray(rules)) throw new TypeError('rules must be an array');

  function validRecord(value, allowEmptyGroups) {
    return value !== null && typeof value === 'object' && !Array.isArray(value) &&
      typeof value.resource === 'string' && value.resource.length > 0 &&
      typeof value.action === 'string' && value.action.length > 0 &&
      Array.isArray(value.groups) && (allowEmptyGroups || value.groups.length > 0) &&
      value.groups.every((group) => typeof group === 'string' && group.length > 0);
  }

  for (const rule of rules) {
    if (!validRecord(rule, false)) throw new TypeError('invalid rule');
  }
  if (!validRecord(request, true)) throw new TypeError('invalid request');

  const requestedGroups = new Set(request.groups);
  for (let i = rules.length - 1; i >= 0; i -= 1) {
    const rule = rules[i];
    if (rule.resource !== request.resource || rule.action !== request.action) continue;
    const group = rule.groups.find((candidate) => requestedGroups.has(candidate));
    if (group !== undefined) return { allowed: true, ruleIndex: i, group };
  }
  return { allowed: false, ruleIndex: -1, group: null };
}

module.exports = { resolveAccess };

