'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['resolveAccess']);
const { resolveAccess } = api;

const rules = [
  { resource: 'report', action: 'read', groups: ['ops', 'admin'] },
  { resource: 'report', action: 'read', groups: ['admin', 'ops'] },
  { resource: 'report', action: 'write', groups: ['admin'] }
];
assert.deepStrictEqual(
  resolveAccess(rules, { resource: 'report', action: 'read', groups: ['admin', 'ops'] }),
  { allowed: true, ruleIndex: 0, group: 'ops' }
);
assert.deepStrictEqual(
  resolveAccess(rules, { resource: 'report', action: 'write', groups: ['admin'] }),
  { allowed: true, ruleIndex: 2, group: 'admin' }
);
assert.deepStrictEqual(
  resolveAccess(rules, { resource: 'Report', action: 'read', groups: ['ops'] }),
  { allowed: false, ruleIndex: -1, group: null }
);
assert.deepStrictEqual(resolveAccess([], { resource: 'x', action: 'y', groups: [] }), {
  allowed: false, ruleIndex: -1, group: null
});
assert.deepStrictEqual(
  resolveAccess([{ resource: 'x', action: 'y', groups: ['a', 'a', 'b'] }], {
    resource: 'x', action: 'y', groups: ['b', 'a', 'a']
  }),
  { allowed: true, ruleIndex: 0, group: 'a' }
);

const stableRules = [{ resource: 'x', action: 'y', groups: ['g'], extra: true }];
const request = { resource: 'x', action: 'y', groups: ['g'], extra: false };
const rulesBefore = JSON.parse(JSON.stringify(stableRules));
const requestBefore = JSON.parse(JSON.stringify(request));
const result = resolveAccess(stableRules, request);
assert.deepStrictEqual(stableRules, rulesBefore);
assert.deepStrictEqual(request, requestBefore);
assert.notStrictEqual(result, stableRules[0]);
assert.deepStrictEqual(Object.keys(result), ['allowed', 'ruleIndex', 'group']);

for (const badRules of [null, {}, 'rules']) {
  assert.throws(() => resolveAccess(badRules, { resource: 'x', action: 'y', groups: [] }), TypeError);
}
for (const badRule of [null, [], new Date(), {}, { resource: '', action: 'y', groups: ['g'] }, { resource: 'x', action: '', groups: ['g'] }, { resource: 'x', action: 'y', groups: [] }, { resource: 'x', action: 'y', groups: 'g' }, { resource: 'x', action: 'y', groups: [''] }, { resource: 1, action: 'y', groups: ['g'] }]) {
  assert.throws(() => resolveAccess([badRule], { resource: 'x', action: 'y', groups: [] }), TypeError);
}
for (const badRequest of [null, [], new Date(), {}, { resource: '', action: 'y', groups: [] }, { resource: 'x', action: '', groups: [] }, { resource: 'x', action: 'y', groups: 'g' }, { resource: 'x', action: 'y', groups: [''] }, { resource: 'x', action: 'y', groups: [1] }]) {
  assert.throws(() => resolveAccess([], badRequest), TypeError);
}
assert.throws(
  () => resolveAccess([
    { resource: 'x', action: 'y', groups: ['g'] },
    { resource: 'bad', action: 'rule', groups: [] }
  ], { resource: 'x', action: 'y', groups: ['g'] }),
  TypeError
);
const sparseRules = new Array(1);
assert.throws(() => resolveAccess(sparseRules, { resource: 'x', action: 'y', groups: [] }), TypeError);

